  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') rawLines.pop()

  const tasks = new Map()
  const edges = []
  const nameUses = []

  rawLines.forEach((rawLine, index) => {
    const lineNo = index + 1
    const trimmed = rawLine.trim()
    if (trimmed === '' || trimmed.startsWith('#')) return
    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) throw new CliError(2, `error: line ${lineNo}: expected task <name> <cost>`)
      const [, name, costStr] = words
      if (!NAME_RE.test(name)) throw new CliError(2, `error: line ${lineNo}: invalid task name ${name}`)
      if (!COST_RE.test(costStr)) throw new CliError(2, `error: line ${lineNo}: cost must be a non-negative integer`)
      if (tasks.has(name)) throw new CliError(2, `error: line ${lineNo}: task ${name} is declared twice`)
      tasks.set(name, parseInt(costStr, 10))
    } else if (directive === 'dep') {
      if (words.length < 3) throw new CliError(2, `error: line ${lineNo}: expected dep <name> <dependency>...`)
      const name = words[1]
      if (!NAME_RE.test(name)) throw new CliError(2, `error: line ${lineNo}: invalid task name ${name}`)
      nameUses.push(name)
      for (let i = 2; i < words.length; i++) {
        const dep = words[i]
        if (!NAME_RE.test(dep)) throw new CliError(2, `error: line ${lineNo}: invalid task name ${dep}`)
        nameUses.push(dep)
        edges.push({ from: name, to: dep })
      }
    } else {
      throw new CliError(2, `error: line ${lineNo}: unknown directive ${directive}`)
    }
  })

  for (const name of nameUses) {
    if (!tasks.has(name)) throw new CliError(2, `error: unknown task ${name}`)
  }

  const dependencies = new Map()
  for (const name of tasks.keys()) dependencies.set(name, new Set())
  for (const edge of edges) dependencies.get(edge.from).add(edge.to)

  const adjacency = new Map()
  for (const [name, deps] of dependencies) adjacency.set(name, [...deps].sort())

  return { tasks, adjacency }
}
