  const start = new Map()
  const finish = new Map()
  const depth = new Map()

  function compute(name) {
    if (finish.has(name)) return
    let s = 0
    let d = 0
    for (const dep of adjacency.get(name)) {
      compute(dep)
      s = Math.max(s, finish.get(dep))
      d = Math.max(d, depth.get(dep) + 1)
    }
    start.set(name, s)
    finish.set(name, s + tasks.get(name))
    depth.set(name, d)
  }

  for (const name of tasks.keys()) compute(name)
  return { start, finish, depth }
}

/**
 * Computes each task's scheduling priority: the cost of the longest chain
 * of costs starting at that task and following its dependents down to a
 * task nothing depends on.
 */
export function computePriorities(tasks, adjacency) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, deps] of adjacency) {
